(function(root){
const norm=v=>String(v??'').normalize('NFKC').toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
function price(v){if(typeof v==='number')return Number.isFinite(v)&&v>=0?v:null;if(typeof v!=='string')return null;let s=v.replace(/[\s\u00a0₽]/g,'').replace(/руб\.?$/i,'').replace(',','.');return /^\d+(\.\d+)?$/.test(s)?Number(s):null}
function detect(rows){let best=0,score=-1;rows.slice(0,40).forEach((r,i)=>{let n=r.map(norm);let s=n.reduce((a,v)=>a+(/^(код|артикул|sku|номенклатура|наименование|название|цена|price)/.test(v)?1:0),0);if(s>score){score=s;best=i}});let h=rows[best]||[];const find=re=>h.findIndex(x=>re.test(norm(x)));return {header:best,code:find(/^(код|артикул|sku)/),name:find(/^(номенклатура|наименование|название|товар)/),price:find(/^(цена|price|стоимость за)/)}}
function match(base,sources,mode){const codes=new Map(),names=new Map();function add(map,key,c){if(key){if(!map.has(key))map.set(key,[]);map.get(key).push(c)}}for(const s of sources)for(let i=s.header+1;i<s.rows.length;i++){const r=s.rows[i]||[],p=price(r[s.price]);if(p===null)continue;const c={price:p,source:s.filename,sheet:s.sheet,row:i+1};add(codes,norm(r[s.code]),c);add(names,norm(r[s.name]),c)}const out=[];for(let i=base.header+1;i<base.rows.length;i++){const r=base.rows[i]||[],code=r[base.code],name=r[base.name];if(!norm(name)&&!norm(code))continue;if(base.name>=0&&!norm(name))continue;let candidates=[],by='';if(mode!=='name'&&norm(code)){candidates=codes.get(norm(code))||[];if(candidates.length)by='код'}if(!candidates.length&&mode!=='code'&&norm(name)){candidates=names.get(norm(name))||[];if(candidates.length)by='название'}const unique=[...new Map(candidates.map(c=>[c.price,c])).values()];out.push({row:i,code:code??'',name:name??'',old:base.price<0?null:r[base.price],candidates:unique,chosen:unique.length===1?0:-1,status:unique.length===0?'missing':unique.length===1?'found':'conflict',by})}return out}
function matchMulti(base,sources,mode){const codes=new Map(),names=new Map();function add(map,key,c){if(key){if(!map.has(key))map.set(key,[]);map.get(key).push(c)}}
for(let si=0;si<sources.length;si++){const s=sources[si],h=s.rows[s.header]||[];for(let i=s.header+1;i<s.rows.length;i++){const r=s.rows[i]||[];for(const col of s.prices){const p=price(r[col]);if(p===null)continue;const c={price:p,source:s.filename,sheet:s.sheet,row:i+1,si,col,label:String(h[col]||'Цена '+(col+1))};if(s.code>=0)add(codes,norm(r[s.code]),c);if(s.name>=0)add(names,norm(r[s.name]),c)}}}
const out=[];for(let i=base.header+1;i<base.rows.length;i++){const r=base.rows[i]||[],code=base.code>=0?r[base.code]:'',name=base.name>=0?r[base.name]:'';if(!norm(code)&&!norm(name))continue;let candidates=[],by='';if(mode!=='name'&&norm(code)){candidates=codes.get(norm(code))||[];if(candidates.length)by='код'}if(!candidates.length&&mode!=='code'&&norm(name)){candidates=names.get(norm(name))||[];if(candidates.length)by='название'}
const unique=[...new Map(candidates.map(c=>[c.si+':'+c.col+':'+c.price,c])).values()];out.push({row:i,code:code??'',name:name??'',old:base.price<0?null:r[base.price],candidates:unique,chosen:unique.length===1?0:-1,status:unique.length===0?'missing':unique.length===1?'found':'conflict',by})}return out}
const api={norm,price,detect,match,matchMulti};root.PriceEngine=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
